import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"Fetch Text","description":"","frontmatter":{"prev":{"text":"Field Types","link":"/documentation/form-fields/field-types"},"next":{"text":"Fetch HTML","link":"/documentation/field-types/scraper-data/fetch-html"}},"headers":[],"relativePath":"documentation/field-types/scraper-data/fetch-text.md","filePath":"documentation/field-types/scraper-data/fetch-text.md","lastUpdated":1791360312000}`),a={name:`documentation/field-types/scraper-data/fetch-text.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="fetch-text" tabindex="-1">Fetch Text <a class="header-anchor" href="#fetch-text" aria-label="Permalink to “Fetch Text”">​</a></h1><p>The <strong>Fetch Text</strong> field type extracts plain text content from a targeted web page element and stores it directly into your site&#39;s <a href="/documentation/site/site-scraper-data.html">Scraper Data</a> dataset.</p><p>Extracted text can be reviewed in real time, exported to an Excel (<code>.xlsx</code>) workbook, or referenced dynamically by subsequent form fields using <code>{$fieldName$}</code> syntax.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>When automating workflows, you frequently need to read data generated by the web page (such as confirmation numbers, account IDs, verification codes, or status messages) after completing an action.</p><p><strong>Fetch Text</strong> extracts the visible inner text (<code>innerText</code>) from the DOM element matched by your selector.</p><table tabindex="0"><thead><tr><th>Property</th><th>Behavior</th><th>Example Output</th></tr></thead><tbody><tr><td><strong>Visible Text Extraction</strong></td><td>Strips HTML tags and captures clean text content.</td><td><code>&lt;div class=&quot;badge&quot;&gt;Success&lt;/div&gt;</code> → <code>Success</code></td></tr><tr><td><strong>Data Storage</strong></td><td>Automatically creates a column named after the field in <a href="/documentation/site/site-scraper-data.html">Scraper Data</a>.</td><td>Saved in active <code>.xlsx</code> dataset row</td></tr><tr><td><strong>Dynamic Reuse</strong></td><td>Enables downstream fields to inject the extracted text using <code>{$fieldName$}</code>.</td><td>Injected into next form input</td></tr></tbody></table><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th style="text-align:center;">Required</th></tr></thead><tbody><tr><td><strong>Selector Type</strong></td><td>Dropdown</td><td>Method used to locate the element (<code>CSS Selector</code> or <code>XPath</code>).</td><td style="text-align:center;">Yes</td></tr><tr><td><strong>Selector Query</strong></td><td>Text Input</td><td>CSS selector or XPath query targeting the element containing the text.</td><td style="text-align:center;">Yes</td></tr><tr><td><strong>Wait until element is found in the page</strong></td><td>Toggle</td><td>Pauses execution until the element mounts in the DOM (useful for asynchronous/AJAX content).</td><td style="text-align:center;">No</td></tr></tbody></table><hr><h2 id="usage" tabindex="-1">Step-by-Step Usage <a class="header-anchor" href="#usage" aria-label="Permalink to “Step-by-Step Usage”">​</a></h2><ol><li>Open your target <strong>Site Form</strong> or <strong>Segment</strong> in the Excellent Data Filler dashboard.</li><li>Click <strong>Insert Field</strong> (<code>+</code>) and select <strong>Fetch Text</strong> under the <strong>Scraper Data</strong> category.</li><li>Name your field descriptively (e.g., <code>OrderConfirmationNumber</code>).</li><li>Enter the <strong>Selector Query</strong> pointing to the element containing the text: <ul><li>Example CSS Selector: <code>#order-summary span.order-id</code></li><li>Example XPath: <code>//div[@class=&#39;confirmation-box&#39;]/h3</code></li></ul></li><li><em>(Optional)</em> Turn on <strong>Wait until element is found in the page</strong> if the text renders dynamically after an AJAX submission.</li><li>Click <strong>Save</strong> to confirm.</li></ol><hr><h2 id="example" tabindex="-1">Example Scenario: Capturing Generated Order IDs <a class="header-anchor" href="#example" aria-label="Permalink to “Example Scenario: Capturing Generated Order IDs”">​</a></h2><p>After submitting a purchase or registration form, the confirmation page displays:</p><div class="language-html" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;result-box&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Thank you for your order!&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Your tracking number is: &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tracking-num&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;TRK-984210&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="setup" tabindex="-1">Setup: <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup:”">​</a></h3><ul><li><strong>Field Name</strong>: <code>TrackingNumber</code></li><li><strong>Field Type</strong>: <code>Fetch Text</code></li><li><strong>Selector Query</strong>: <code>#tracking-num</code></li></ul><h3 id="execution-result" tabindex="-1">Execution Result: <a class="header-anchor" href="#execution-result" aria-label="Permalink to “Execution Result:”">​</a></h3><ol><li>When the page loads, the extension reads <code>#tracking-num</code> and captures <code>TRK-984210</code>.</li><li>The value is logged and stored in the <strong>Scraper Data</strong> table under column <code>TrackingNumber</code>.</li><li>If your workflow continues to a follow-up form or email step, subsequent fields can reference <code>{$TrackingNumber$}</code> to automatically insert <code>TRK-984210</code>.</li><li>When automation finishes, export the entire dataset as an Excel (<code>.xlsx</code>) spreadsheet from the <strong>Scraper Data</strong> dashboard.</li></ol><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Use Precise Selectors</strong>: Target the innermost text-containing element (e.g., <code>span.order-id</code> rather than the parent <code>div.container</code>) to avoid capturing unwanted whitespace or adjacent labels.</li><li><strong>Handling Delayed Rendering</strong>: Enable <strong>Wait until element is found</strong> on Single Page Applications (SPAs) where confirmation details appear after a server response delay.</li><li><strong>Context Helper</strong>: Use <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>C</kbd> or right-click → <strong>Copy Element Selector Address</strong> to easily copy the target element&#39;s selector directly from the browser page.</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};